"""Bundle desktop/plugin.js from the pane sources.

Hermes loads the one file. Disk plugins may import only @hermes/plugin-sdk,
react, and react/jsx-runtime, so the view and the stylesheet are inlined.
"""

from __future__ import annotations

import json
from pathlib import Path

HERE = Path(__file__).resolve().parent


def render_plugin() -> str:
    css = (HERE / "pane.css").read_text(encoding="utf-8")
    dom = (HERE / "pane-dom.js").read_text(encoding="utf-8")
    register = (HERE / "register.js").read_text(encoding="utf-8")
    return (
        "// Generated by plugin/desktop/build_plugin.py. Do not edit by hand.\n"
        "// Rebuild with: python plugin/desktop/build_plugin.py\n\n"
        'import { host } from "@hermes/plugin-sdk";\n'
        'import { jsx } from "react/jsx-runtime";\n'
        'import { useEffect, useRef, useState } from "react";\n\n'
        f"const PANE_CSS = {json.dumps(css)};\n\n"
        f"{dom}\n"
        f"{register}"
    )


def main() -> None:
    target = HERE / "plugin.js"
    target.write_text(render_plugin(), encoding="utf-8")


if __name__ == "__main__":
    main()
